let timers = [];
function addTimer(fn, ms) {
  const id = setInterval(fn, ms);
  timers.push(id);
  return id;
}
function clearAllTimers() {
  timers.forEach(id => clearInterval(id));
  timers = [];
}
// 在 gameOver/restart 时调用 clearAllTimers()

